{
  "id": "ad-hooks",
  "title": "Ad hook variants",
  "description": "Opening hooks for a vertical UGC-style ad, tested the clean way: one presenter the user picks, and only the spoken line changes from clip to clip.",
  "parameters": [
    {
      "id": "brief",
      "label": "Brief",
      "type": "text",
      "input": "brief",
      "description": "The product, who it is for, the offer, and the facts the ad may state, in the user's words."
    },
    {
      "id": "product",
      "label": "Product photo",
      "type": "file",
      "input": "product",
      "description": "Optional: the real product, so the presenter holds it."
    },
    {
      "id": "presenter",
      "label": "Presenter",
      "type": "text",
      "default": "a relaxed, natural creator at home",
      "description": "Who speaks and where, fitted to the audience, e.g. a woman in her 30s in a bright kitchen."
    },
    {
      "id": "count",
      "label": "Hooks written",
      "type": "number",
      "default": 6,
      "minimum": 2,
      "maximum": 24
    },
    {
      "id": "keep",
      "label": "Hooks to film",
      "type": "number",
      "default": 3,
      "minimum": 1,
      "maximum": 8
    }
  ],
  "spec": {
    "title": "Ad hooks",
    "description": "A picked presenter, written hooks, a pick, then a talking clip per hook.",
    "steps": [
      {
        "id": "brief",
        "type": "input",
        "label": "Brief",
        "config": {
          "kind": "text",
          "needed": "the product, audience, offer and facts"
        }
      },
      {
        "id": "product",
        "type": "input",
        "label": "Product photo",
        "config": {
          "kind": "image",
          "optional": true,
          "needed": "your product photo (optional)"
        }
      },
      {
        "id": "presenters",
        "type": "generate",
        "label": "Presenters",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 3,
          "prompt": "A vertical selfie-style phone frame of {{presenter}}, looking into the lens, natural light, holding the product from the reference if there is one. A fictional person. No on-screen text.",
          "settings": {
            "aspectRatio": "9:16",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "product",
            "port": "media"
          }
        ]
      },
      {
        "id": "cast",
        "type": "choose",
        "label": "Pick the presenter",
        "config": {
          "pick": 1,
          "by": "person"
        },
        "inputs": [
          {
            "from": "presenters"
          }
        ]
      },
      {
        "id": "hooks",
        "type": "write",
        "label": "Hooks",
        "config": {
          "output": "list",
          "items": "{{count}}",
          "prompt": "Write {{count}} opening lines for a vertical UGC-style ad, each a different angle (a problem, a question, a surprising demo, a bold contrast). Each is one line of at most 15 words that a presenter says to camera. Use only facts from the brief: no invented claims, numbers or personal testimonials. Return only the lines."
        },
        "inputs": [
          {
            "from": "brief"
          }
        ]
      },
      {
        "id": "pick",
        "type": "choose",
        "label": "Hooks to film",
        "config": {
          "pick": "{{keep}}",
          "by": "person"
        },
        "inputs": [
          {
            "from": "hooks"
          }
        ]
      },
      {
        "id": "clips",
        "type": "generate",
        "label": "Hook clips",
        "config": {
          "kind": "video",
          "model": "veo-3.1-fast",
          "count": 1,
          "prompt": "Handheld selfie video. The person says this line to camera, naturally and clearly: \"{{text}}\" Room sound only, no music.",
          "settings": {
            "duration": 8,
            "aspectRatio": "9:16",
            "resolution": "720p",
            "audio": true
          }
        },
        "inputs": [
          {
            "from": "cast",
            "port": "media"
          },
          {
            "from": "pick",
            "port": "text",
            "each": true
          }
        ]
      },
      {
        "id": "review",
        "type": "review",
        "label": "Review",
        "config": {
          "note": "Is each line spoken exactly and in sync, with the product right?"
        },
        "inputs": [
          {
            "from": "clips"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Hook clips",
        "config": {
          "name": "Hook clips",
          "save": true
        },
        "inputs": [
          {
            "from": "review"
          }
        ]
      }
    ]
  }
}

{
  "id": "concepts-to-video",
  "title": "Concepts → choose → video",
  "description": "Written concepts become stills side by side; the user picks one, and only the pick is animated, then reviewed.",
  "parameters": [
    {
      "id": "brief",
      "label": "Brief",
      "type": "text",
      "input": "brief",
      "description": "What the piece is for, the product and the feeling, in the user's words."
    },
    {
      "id": "refs",
      "label": "Seed images",
      "type": "file",
      "input": "refs",
      "description": "Optional: the product, a character or a mood board the stills should follow."
    },
    {
      "id": "count",
      "label": "Concepts",
      "type": "number",
      "default": 4,
      "minimum": 2,
      "maximum": 24
    },
    {
      "id": "style",
      "label": "Look",
      "type": "text",
      "default": "one look that fits the brief"
    },
    {
      "id": "aspectRatio",
      "label": "Aspect ratio",
      "type": "text",
      "options": ["16:9", "9:16"],
      "default": "16:9"
    },
    {
      "id": "seconds",
      "label": "Video length (s)",
      "type": "number",
      "default": 6,
      "options": [4, 6, 8]
    }
  ],
  "spec": {
    "title": "Concepts → video",
    "description": "Concepts, a pick, a motion prompt for the pick, then its video.",
    "steps": [
      {
        "id": "brief",
        "type": "input",
        "label": "Brief",
        "config": {
          "kind": "text",
          "needed": "your brief"
        }
      },
      {
        "id": "refs",
        "type": "input",
        "label": "Seed images",
        "config": {
          "kind": "image",
          "multiple": true,
          "optional": true,
          "needed": "seed images (optional)"
        }
      },
      {
        "id": "concepts",
        "type": "write",
        "label": "Concepts",
        "config": {
          "output": "list",
          "items": "{{count}}",
          "prompt": "Write {{count}} clearly different visual concepts for this brief. Each is one sentence an image model can draw: the subject, the setting, the composition and the light. Keep one shared look: {{style}}."
        },
        "inputs": [
          {
            "from": "brief"
          },
          {
            "from": "refs"
          }
        ]
      },
      {
        "id": "stills",
        "type": "generate",
        "label": "Stills",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 1,
          "prompt": "{{text}}",
          "settings": {
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "concepts",
            "port": "text",
            "each": true
          },
          {
            "from": "refs",
            "port": "media"
          }
        ]
      },
      {
        "id": "pick",
        "type": "choose",
        "label": "Pick a concept",
        "config": {
          "pick": 1,
          "by": "person"
        },
        "inputs": [
          {
            "from": "stills"
          }
        ]
      },
      {
        "id": "motion",
        "type": "write",
        "label": "Motion",
        "config": {
          "output": "text",
          "prompt": "Write the motion prompt that animates this frame for the brief: what moves, how the camera responds and how the shot ends, in one or two sentences. Describe motion only; the frame already sets the scene."
        },
        "inputs": [
          {
            "from": "pick"
          },
          {
            "from": "brief"
          }
        ]
      },
      {
        "id": "video",
        "type": "generate",
        "label": "Video",
        "config": {
          "kind": "video",
          "model": "veo-3.1-fast",
          "count": 1,
          "prompt": "{{text}}",
          "settings": {
            "duration": "{{seconds}}",
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "720p"
          }
        },
        "inputs": [
          {
            "from": "pick",
            "port": "media"
          },
          {
            "from": "motion",
            "port": "text"
          }
        ]
      },
      {
        "id": "review",
        "type": "review",
        "label": "Review",
        "config": {
          "note": "Does the motion fit the concept?"
        },
        "inputs": [
          {
            "from": "video"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Final video",
        "config": {
          "name": "Final video",
          "save": true
        },
        "inputs": [
          {
            "from": "review"
          }
        ]
      }
    ]
  }
}

{
  "id": "consistent-character",
  "title": "Character across shots",
  "description": "The character is designed and picked first; every frame then uses the pick as its reference, the user approves the frames, and each becomes a shot.",
  "parameters": [
    {
      "id": "character",
      "label": "Character",
      "type": "text",
      "input": "character",
      "description": "Who the character is and how they look, in the user's words."
    },
    {
      "id": "story",
      "label": "Story",
      "type": "text",
      "input": "story",
      "description": "What happens across the shots."
    },
    {
      "id": "looks",
      "label": "Looks",
      "type": "number",
      "default": 4,
      "minimum": 2,
      "maximum": 8
    },
    {
      "id": "shots",
      "label": "Shots",
      "type": "number",
      "default": 4,
      "minimum": 2,
      "maximum": 24
    },
    {
      "id": "style",
      "label": "Look",
      "type": "text",
      "description": "One concrete look for the character and every frame, e.g. 3D animated feature, soft clay; or grainy 35 mm film."
    },
    {
      "id": "aspectRatio",
      "label": "Aspect ratio",
      "type": "text",
      "options": ["16:9", "9:16"],
      "default": "16:9"
    },
    {
      "id": "seconds",
      "label": "Shot length (s)",
      "type": "number",
      "default": 4,
      "options": [4, 6, 8]
    }
  ],
  "spec": {
    "title": "Character shots",
    "description": "A picked character, then a frame and a shot per beat that all use it.",
    "steps": [
      {
        "id": "character",
        "type": "input",
        "label": "Character",
        "config": {
          "kind": "text",
          "needed": "who the character is and how they look"
        }
      },
      {
        "id": "story",
        "type": "input",
        "label": "Story",
        "config": {
          "kind": "text",
          "needed": "what happens"
        }
      },
      {
        "id": "designs",
        "type": "generate",
        "label": "Character looks",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": "{{looks}}",
          "prompt": "Character design: {{text}} Full body, front three-quarter view, neutral pose, plain light background. Look: {{style}}.",
          "settings": {
            "aspectRatio": "3:4",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "character",
            "port": "text"
          }
        ]
      },
      {
        "id": "cast",
        "type": "choose",
        "label": "Pick the character",
        "config": {
          "pick": 1,
          "by": "person"
        },
        "inputs": [
          {
            "from": "designs"
          }
        ]
      },
      {
        "id": "beats",
        "type": "write",
        "label": "Beats",
        "config": {
          "output": "list",
          "items": "{{shots}}",
          "prompt": "Break the story into {{shots}} shots in screen order. Each shot: \"Frame:\" one sentence for the still (what the character does, where, the framing and light), then \"Motion:\" how the character and camera move. Vary the framing from shot to shot."
        },
        "inputs": [
          {
            "from": "story"
          },
          {
            "from": "character"
          }
        ]
      },
      {
        "id": "frames",
        "type": "generate",
        "label": "Frames",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 1,
          "prompt": "{{text}}\n\nDraw the Frame only, as one still. The character is the one in the reference: same face, hair, clothes and proportions. Look: {{style}}. No text.",
          "settings": {
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "beats",
            "port": "text",
            "each": true
          },
          {
            "from": "cast",
            "port": "media"
          }
        ]
      },
      {
        "id": "approve",
        "type": "review",
        "label": "Approve frames",
        "config": {
          "note": "Is it the same character in every frame?"
        },
        "inputs": [
          {
            "from": "frames"
          }
        ]
      },
      {
        "id": "shots",
        "type": "generate",
        "label": "Shots",
        "config": {
          "kind": "video",
          "model": "veo-3.1-fast",
          "count": 1,
          "prompt": "Animate this frame as the Motion line says. {{text}}",
          "settings": {
            "duration": "{{seconds}}",
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "720p"
          }
        },
        "inputs": [
          {
            "from": "approve",
            "port": "media",
            "each": true
          },
          {
            "from": "beats",
            "port": "text",
            "each": true
          }
        ]
      },
      {
        "id": "review",
        "type": "review",
        "label": "Review shots",
        "config": {
          "note": "Does the character stay the same while moving?"
        },
        "inputs": [
          {
            "from": "shots"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Shots",
        "config": {
          "name": "Character shots",
          "save": true
        },
        "inputs": [
          {
            "from": "review"
          }
        ]
      }
    ]
  }
}

{
  "id": "game-asset-pack",
  "title": "Game asset pack",
  "description": "Style frames for the game's art direction, the user picks one, then a set of props in that style with transparent backgrounds, reviewed together.",
  "parameters": [
    {
      "id": "brief",
      "label": "Art direction",
      "type": "text",
      "input": "brief",
      "description": "The game, its world, the camera view and the look, plus any props the user named, in the user's words."
    },
    {
      "id": "styles",
      "label": "Style frames",
      "type": "number",
      "default": 4,
      "minimum": 2,
      "maximum": 8
    },
    {
      "id": "count",
      "label": "Props",
      "type": "number",
      "default": 20,
      "minimum": 2,
      "maximum": 24
    }
  ],
  "spec": {
    "title": "Asset pack",
    "description": "A picked style, then one transparent prop per item of the list.",
    "steps": [
      {
        "id": "brief",
        "type": "input",
        "label": "Art direction",
        "config": {
          "kind": "text",
          "needed": "the game and its look"
        }
      },
      {
        "id": "styles",
        "type": "generate",
        "label": "Style frames",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": "{{styles}}",
          "prompt": "Style frame for a game's art: {{text}} A few sample props from this world laid out on a plain background, showing the rendering, palette, outlines and lighting the whole asset set will share.",
          "settings": {
            "aspectRatio": "1:1",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "brief",
            "port": "text"
          }
        ]
      },
      {
        "id": "style",
        "type": "choose",
        "label": "Pick the style",
        "config": {
          "pick": 1,
          "by": "person"
        },
        "inputs": [
          {
            "from": "styles"
          }
        ]
      },
      {
        "id": "list",
        "type": "write",
        "label": "Prop list",
        "config": {
          "output": "list",
          "items": "{{count}}",
          "prompt": "List {{count}} props for this game's asset set, the ones the brief names first. Each item is a complete image prompt for one prop on its own: the object, the game's camera view, and the picked style frame's rendering, palette, outlines and lighting described precisely enough that every prop matches it."
        },
        "inputs": [
          {
            "from": "brief"
          },
          {
            "from": "style"
          }
        ]
      },
      {
        "id": "props",
        "type": "generate",
        "label": "Props",
        "config": {
          "kind": "image",
          "model": "openai/gpt-image-2.5/flare/text-to-image",
          "count": 1,
          "prompt": "{{text}} One isolated object, whole and centered, on a transparent background.",
          "settings": {
            "image_size": "square_hd",
            "quality": "medium",
            "background": "transparent",
            "output_format": "png"
          }
        },
        "inputs": [
          {
            "from": "list",
            "port": "text",
            "each": true
          }
        ]
      },
      {
        "id": "review",
        "type": "review",
        "label": "Review props",
        "config": {
          "note": "Do the props share one style and read clearly at game size?"
        },
        "inputs": [
          {
            "from": "props"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Props",
        "config": {
          "name": "Props",
          "save": true
        },
        "inputs": [
          {
            "from": "review"
          }
        ]
      }
    ]
  }
}

{
  "id": "image-edit-chain",
  "title": "Image edit chain",
  "description": "A base image goes through edits in order, each building on the last; the user approves the result and it is upscaled.",
  "parameters": [
    {
      "id": "base",
      "label": "Base image",
      "type": "file",
      "input": "base",
      "description": "The image to start from."
    },
    {
      "id": "edit1",
      "label": "First edit",
      "type": "text",
      "description": "The first change, as an instruction, e.g. make it dusk with warm streetlights."
    },
    {
      "id": "edit2",
      "label": "Second edit",
      "type": "text",
      "description": "The second change, e.g. add light falling snow."
    },
    {
      "id": "aspectRatio",
      "label": "Aspect ratio",
      "type": "text",
      "options": ["16:9", "9:16", "1:1", "4:3", "3:4"],
      "description": "The base image's shape (or the nearest of these)."
    }
  ],
  "spec": {
    "title": "Image edits",
    "description": "Two edits in sequence, a review, then an upscale.",
    "steps": [
      {
        "id": "base",
        "type": "input",
        "label": "Base image",
        "config": {
          "kind": "image",
          "needed": "the image to edit"
        }
      },
      {
        "id": "edit-1",
        "type": "generate",
        "label": "Edit 1",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 1,
          "prompt": "{{edit1}}. Keep everything else in the image exactly as it is.",
          "settings": {
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "base",
            "port": "media"
          }
        ]
      },
      {
        "id": "edit-2",
        "type": "generate",
        "label": "Edit 2",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 1,
          "prompt": "{{edit2}}. Keep everything else in the image exactly as it is.",
          "settings": {
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "edit-1",
            "port": "media"
          }
        ]
      },
      {
        "id": "review",
        "type": "review",
        "label": "Review",
        "config": {
          "note": "Approve before the upscale."
        },
        "inputs": [
          {
            "from": "edit-2"
          }
        ]
      },
      {
        "id": "upscale",
        "type": "generate",
        "label": "Upscale",
        "config": {
          "kind": "image",
          "model": "fal-ai/topaz/upscale/image",
          "count": 1,
          "prompt": "",
          "settings": {}
        },
        "inputs": [
          {
            "from": "review",
            "port": "media"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Final image",
        "config": {
          "name": "Edited image",
          "save": true
        },
        "inputs": [
          {
            "from": "upscale"
          }
        ]
      }
    ]
  }
}

{
  "id": "model-variants",
  "title": "N variants across models",
  "description": "One prompt on several image models at once, side by side, so the user picks the model and the image.",
  "parameters": [
    {
      "id": "prompt",
      "label": "Prompt",
      "type": "text",
      "input": "prompt",
      "description": "The image prompt, the same for every model."
    },
    {
      "id": "count",
      "label": "Images per model",
      "type": "number",
      "default": 1,
      "minimum": 1,
      "maximum": 8
    }
  ],
  "spec": {
    "title": "Model comparison",
    "description": "The same prompt on three image models, then a pick.",
    "steps": [
      {
        "id": "prompt",
        "type": "input",
        "label": "Prompt",
        "config": {
          "kind": "text",
          "needed": "the prompt"
        }
      },
      {
        "id": "nano-banana",
        "type": "generate",
        "label": "Nano Banana 2",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": "{{count}}",
          "prompt": "{{text}}",
          "settings": {
            "aspectRatio": "1:1",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "prompt",
            "port": "text"
          }
        ]
      },
      {
        "id": "flux",
        "type": "generate",
        "label": "FLUX.2 Pro",
        "config": {
          "kind": "image",
          "model": "fal-ai/flux-2-pro",
          "count": "{{count}}",
          "prompt": "{{text}}",
          "settings": {
