{
  "id": "storyboard",
  "title": "Storyboard: beats → frames → approve → shots",
  "description": "A short piece planned as beats: one frame per beat, the user approves the frames, then each approved frame is animated into its shot.",
  "parameters": [
    {
      "id": "brief",
      "label": "Brief",
      "type": "text",
      "input": "brief",
      "description": "The story or message, the audience and the feeling."
    },
    {
      "id": "refs",
      "label": "References",
      "type": "file",
      "input": "refs",
      "description": "Optional: the character, product or look every frame should follow."
    },
    {
      "id": "beats",
      "label": "Beats",
      "type": "number",
      "default": 4,
      "minimum": 2,
      "maximum": 24
    },
    {
      "id": "style",
      "label": "Look",
      "type": "text",
      "default": "one look that fits the brief"
    },
    {
      "id": "aspectRatio",
      "label": "Aspect ratio",
      "type": "text",
      "options": ["16:9", "9:16"],
      "default": "16:9"
    },
    {
      "id": "seconds",
      "label": "Shot length (s)",
      "type": "number",
      "default": 4,
      "options": [4, 6, 8]
    }
  ],
  "spec": {
    "title": "Storyboard",
    "description": "Beats, a frame per beat, approval, a shot per frame, then a review.",
    "steps": [
      {
        "id": "brief",
        "type": "input",
        "label": "Brief",
        "config": {
          "kind": "text",
          "needed": "your brief"
        }
      },
      {
        "id": "refs",
        "type": "input",
        "label": "References",
        "config": {
          "kind": "image",
          "multiple": true,
          "optional": true,
          "needed": "references (optional)"
        }
      },
      {
        "id": "beats",
        "type": "write",
        "label": "Beats",
        "config": {
          "output": "list",
          "items": "{{beats}}",
          "prompt": "Break this brief into {{beats}} beats in screen order. Each beat: \"Frame:\" one sentence an image model can draw (subject, action, composition, light), then \"Motion:\" how the subject and camera move in the shot."
        },
        "inputs": [
          {
            "from": "brief"
          },
          {
            "from": "refs"
          }
        ]
      },
      {
        "id": "frames",
        "type": "generate",
        "label": "Frames",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 1,
          "prompt": "{{text}}\n\nDraw the Frame only, as one still. Look: {{style}}. No text.",
          "settings": {
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "1K"
          }
        },
        "inputs": [
          {
            "from": "beats",
            "port": "text",
            "each": true
          },
          {
            "from": "refs",
            "port": "media"
          }
        ]
      },
      {
        "id": "approve",
        "type": "review",
        "label": "Approve frames",
        "config": {
          "note": "Approve the frames before any video is made."
        },
        "inputs": [
          {
            "from": "frames"
          }
        ]
      },
      {
        "id": "shots",
        "type": "generate",
        "label": "Shots",
        "config": {
          "kind": "video",
          "model": "veo-3.1-fast",
          "count": 1,
          "prompt": "Animate this frame as the Motion line says. {{text}}",
          "settings": {
            "duration": "{{seconds}}",
            "aspectRatio": "{{aspectRatio}}",
            "resolution": "720p"
          }
        },
        "inputs": [
          {
            "from": "approve",
            "port": "media",
            "each": true
          },
          {
            "from": "beats",
            "port": "text",
            "each": true
          }
        ]
      },
      {
        "id": "review",
        "type": "review",
        "label": "Review shots",
        "config": {
          "note": "Does each shot move as planned, with the same subjects as its frame?"
        },
        "inputs": [
          {
            "from": "shots"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Shots",
        "config": {
          "name": "Storyboard shots",
          "save": true
        },
        "inputs": [
          {
            "from": "review"
          }
        ]
      }
    ]
  }
}

{
  "id": "thumbnail-options",
  "title": "Thumbnail options",
  "description": "Thumbnail ideas for one video become text-free images side by side; the user keeps three to test.",
  "parameters": [
    {
      "id": "video",
      "label": "Video",
      "type": "text",
      "input": "video",
      "description": "The video's title and what it delivers, in the user's words."
    },
    {
      "id": "refs",
      "label": "References",
      "type": "file",
      "input": "refs",
      "description": "Optional: frames from the video, or the creator's face, to build the thumbnails from."
    },
    {
      "id": "count",
      "label": "Ideas",
      "type": "number",
      "default": 6,
      "minimum": 4,
      "maximum": 8
    },
    {
      "id": "keep",
      "label": "Keep",
      "type": "number",
      "default": 3,
      "minimum": 1,
      "maximum": 3
    }
  ],
  "spec": {
    "title": "Thumbnail options",
    "description": "Thumbnail ideas, an image each, then the user keeps the best to test.",
    "steps": [
      {
        "id": "video",
        "type": "input",
        "label": "Video",
        "config": {
          "kind": "text",
          "needed": "the video's title and what it delivers"
        }
      },
      {
        "id": "refs",
        "type": "input",
        "label": "References",
        "config": {
          "kind": "image",
          "multiple": true,
          "optional": true,
          "needed": "frames or the creator's face (optional)"
        }
      },
      {
        "id": "ideas",
        "type": "write",
        "label": "Ideas",
        "config": {
          "output": "list",
          "items": "{{count}}",
          "prompt": "Write {{count}} clearly different thumbnail ideas for this video. Each is one sentence an image model can draw: one focal subject, and the emotion or contrast that makes a viewer curious. Keep the same people and visual language; vary the framing, the expression or the focal detail. Leave room for a few optional words. Promise only what the video delivers."
        },
        "inputs": [
          {
            "from": "video"
          },
          {
            "from": "refs"
          }
        ]
      },
      {
        "id": "thumbnails",
        "type": "generate",
        "label": "Thumbnails",
        "config": {
          "kind": "image",
          "model": "nano-banana-2.1",
          "count": 1,
          "prompt": "{{text}} A YouTube thumbnail: bold, simple, high contrast, readable when small. No words or letters.",
          "settings": {
            "aspectRatio": "16:9",
            "resolution": "2K"
          }
        },
        "inputs": [
          {
            "from": "ideas",
            "port": "text",
            "each": true
          },
          {
            "from": "refs",
            "port": "media"
          }
        ]
      },
      {
        "id": "keep",
        "type": "choose",
        "label": "Keep the best",
        "config": {
          "pick": "{{keep}}",
          "by": "person"
        },
        "inputs": [
          {
            "from": "thumbnails"
          }
        ]
      },
      {
        "id": "final",
        "type": "output",
        "label": "Thumbnail options",
        "config": {
          "name": "Thumbnail options",
          "save": true
        },
        "inputs": [
          {
            "from": "keep"
          }
        ]
      }
    ]
  }
}
